properties.query:
// Detects the execution of a ".CPL" file located in the user temp directory via the Shell32 DLL "Control_RunDLL" export function.
//This behavior was observed in multiple Raspberry-Robin variants.
let parent_processes = dynamic(["rundll32.exe"]);
let cmd_any = dynamic(["shell32.dll","Control_RunDLL",".CPL","AppData\\Local\\Temp"]);
_Im_ProcessCreate(parentprocess_has_any=parent_processes,commandline_has_any=cmd_any,targetprocess_has_any="rundll32.exe")
| extend
    Account = tostring(column_ifexists("ActorUsername", "")),
    AccountDomain = tostring(column_ifexists("ActorUserDomain", "")),
    Computer = tostring(column_ifexists("DvcHostname", "")),
    ProcessName = tostring(column_ifexists("TargetProcessName", "")),
    ProcessId = tostring(column_ifexists("TargetProcessId", "")),
    CommandLine = tostring(column_ifexists("CommandLine", ""))
| where isnotempty(ProcessName)
